if (item.json.error || item.json.stop_reason === 'refusal' || !textBlock) {
  extracted.raw_response = item.json.error ? JSON.stringify(item.json.error) : item.json.stop_reason === 'refusal' ? 'REFUSED' : 'API_FAILED_OR_INVALID_RESPONSE';
